<script>document.addEventListener('DOMContentLoaded',function(){const saved=@json($confirmationPayload),year=document.getElementById('extraFiscalYear'),from=document.getElementById('extraPeriodFrom'),to=document.getElementById('extraPeriodTo');if(saved){Object.keys(saved).forEach(function(key){const field=document.querySelector('[name="'+key+'"]');if(field&&saved[key]!==null)field.value=saved[key]});const firm=document.querySelector('[name="firm_id"]');if(firm)firm.value=saved.firm_id; if(year&&saved.period_from_bs){const match=String(saved.period_from_bs).match(/^(\d{4})-04-01$/);if(match)year.value=match[1]}}if(!year||!from||!to)return;year.addEventListener('change',function(){if(!this.value)return;const y=Number(this.value);from.value=y+'-04-01';to.value=(y+1)+'-03-31';});});</script>
<div id="extraFirmModal" style="display:none;position:fixed;inset:0;z-index:1050;background:rgba(0,0,0,.45);padding:5vh 15px;overflow:auto"><div style="max-width:620px;margin:auto;background:#fff;border-radius:12px;box-shadow:0 10px 40px rgba(0,0,0,.25)"><div class="d-flex justify-content-between align-items-center p-3 border-bottom"><h5 class="mb-0 text-primary">Add Firm</h5><button type="button" id="closeExtraFirmModal" class="btn-close" aria-label="Close"></button></div><form id="extraFirmForm"><div class="p-3"><div id="extraFirmError" class="alert alert-danger d-none"></div><div class="mb-3"><label class="form-label fw-bold">Firm Name *</label><input name="name" class="form-control" required></div><div class="row g-3"><div class="col-md-6"><label class="form-label fw-bold">PAN/VAT No.</label><input name="pan_no" class="form-control"></div><div class="col-md-6"><label class="form-label fw-bold">Phone</label><input name="phone" class="form-control"></div><div class="col-12"><label class="form-label fw-bold">Address</label><input name="address" class="form-control"></div><div class="col-12"><label class="form-label fw-bold">Email</label><input type="email" name="email" class="form-control"></div></div></div><div class="d-flex justify-content-end gap-2 p-3 border-top"><button type="button" id="cancelExtraFirm" class="btn btn-secondary">Cancel</button><button type="submit" class="btn btn-primary" id="saveExtraFirm"><i class="fa fa-save me-1"></i>Save Firm</button></div></form></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){const select=document.querySelector('select[name="firm_id"]'),modal=document.getElementById('extraFirmModal'),form=document.getElementById('extraFirmForm'),error=document.getElementById('extraFirmError'),close=document.getElementById('closeExtraFirmModal'),cancel=document.getElementById('cancelExtraFirm'),save=document.getElementById('saveExtraFirm');if(!select||!modal||!form)return;const add=document.createElement('button');add.type='button';add.className='btn btn-outline-primary mt-2';add.innerHTML='<i class="fa fa-plus me-1"></i>Add Firm';select.parentElement.appendChild(add);const hide=()=>{modal.style.display='none';form.reset();error.classList.add('d-none');error.textContent=''};add.addEventListener('click',()=>{modal.style.display='block';form.querySelector('[name="name"]').focus()});close.addEventListener('click',hide);cancel.addEventListener('click',hide);modal.addEventListener('click',e=>{if(e.target===modal)hide()});form.addEventListener('submit',async function(e){e.preventDefault();error.classList.add('d-none');save.disabled=true;try{const response=await fetch('{{ route('extra-balance-confirmation.firms.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:new FormData(form)});const data=await response.json();if(!response.ok){const messages=data.errors?Object.values(data.errors).flat().join(' '):(data.message||'Unable to save firm.');throw new Error(messages)}select.add(new Option(data.name,data.id));select.value=data.id;hide()}catch(exception){error.textContent=exception.message;error.classList.remove('d-none')}finally{save.disabled=false}})});</script>
<script>document.addEventListener('DOMContentLoaded',function(){const input=document.getElementById('savedConfirmationSearch'),form=document.getElementById('savedConfirmationSearchForm');if(!input||!form)return;let timer;input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(function(){form.submit()},350)});});</script>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('input[name$="_taxable"]').forEach(function(taxable){const vatName=taxable.name.replace(/_taxable$/,'_vat'),vat=document.querySelector('input[name="'+vatName+'"]');if(!vat)return;const calculate=function(){const amount=parseFloat(taxable.value);vat.value=Number.isFinite(amount)?(amount*.13).toFixed(2):'0'};taxable.addEventListener('input',calculate);taxable.addEventListener('change',calculate)});});</script>
